/* Protótipo 0.8: estoque por produto em unidades, clientes variados e gestão. */
const GOODS={arroz:{name:'Arroz',cost:1,reference:2,color:'#d8bc79',target:18},leite:{name:'Leite',cost:1.5,reference:3,color:'#a1d5d5',target:12},cafe:{name:'Café',cost:3,reference:6,color:'#b68365',target:6}};
const IDS=Object.keys(GOODS),LOCS=['receiving','pallet','rack','sales','player','worker','worker2'];
const UPGRADES={cart:{name:'Carrinho',cost:60,description:'Carregue até 18 unidades por viagem (3 caixas).'},shelf:{name:'Expositor ampliado',cost:80,description:'Capacidade de venda passa de 36 para 60 unidades.'},scanner:{name:'Leitor de caixa',cost:90,description:'Atendimento passa de 3 para 1,5 segundos.'},workflow:{name:'Rotina de abastecimento',cost:120,description:'Libera a atividade contínua Abastecer: transportar e repor em um ciclo atribuído por você.'}};
function freshEconomy(){return {version:8,inv:Object.fromEntries(LOCS.map(k=>[k,Object.fromEntries(IDS.map(p=>[p,0]))])),stock:{},orders:[],prices:{arroz:2,leite:3,cafe:6},purchased:{arroz:0,leite:0,cafe:0},sold:{arroz:0,leite:0,cafe:0},cash:300,day:1,revenue:0,cost:0,purchases:0,investments:0,missed:0,expensive:0,open:false,closing:false,task:'Parado',room:'street',workerRoom:'stock',player:[400,370],worker:[650,300],worker2:{pos:[580,310],room:'stock',task:'Parado',dest:'pallet'},dest:'pallet',customers:[],nextCustomer:1,arrival:0,upgrades:[],mode:'continuous',continuous:false,rng:123456,metrics:{manual:{clicks:0,sales:0,seconds:0},continuous:{clicks:0,sales:0,seconds:0}},byProduct:Object.fromEntries(IDS.map(p=>[p,{sold:0,revenue:0,cost:0,stockLost:0,priceLost:0}])),history:[]}}
let selected='arroz',transportSelected='arroz',workerMessage='',lastEconomyUI=0;
initial=freshEconomy;s=freshEconomy();playerPath=[];workerPath=[];workerGoal='';doorTarget=null;target=null;
function total(location){return Object.values(s.inv[location]).reduce((a,b)=>a+b,0)}
function unitCap(location){return location==='player'?(s.upgrades.includes('cart')?18:6):(location==='worker'||location==='worker2')?6:location==='sales'?(s.upgrades.includes('shelf')?60:36):({receiving:72,pallet:108,rack:36})[location]}
cap=k=>unitCap(k)/6;
function syncStock(){for(let k of LOCS)s.stock[k]=total(k)/6;s.stock.baskets=s.customers.reduce((a,c)=>a+(c.basket?c.quantity:0),0)/6}
function random(){s.rng=(Math.imul(1664525,s.rng)+1013904223)>>>0;return s.rng/4294967296}
function pendingUnits(p){return s.orders.reduce((n,o)=>n+(!p||p===o.product?o.pending:0),0)}
pending=()=>pendingUnits()/6;
conserved=function(){return IDS.every(p=>LOCS.reduce((n,k)=>n+s.inv[k][p],0)+pendingUnits(p)+s.customers.reduce((n,c)=>n+(c.basket&&c.product===p?c.quantity:0),0)+s.sold[p]===s.purchased[p])};
function transferUnits(from,to,p,amount){if(from===to||!LOCS.includes(from)||!LOCS.includes(to)||!IDS.includes(p))return 0;let q=Math.max(0,Math.min(Math.floor(amount),s.inv[from][p],unitCap(to)-total(to)));if(q){s.inv[from][p]-=q;s.inv[to][p]+=q}syncStock();return q}
move=(a,b,n)=>transferUnits(a,b,transportSelected,Math.floor(n*6))/6;
function receive(){for(let o of s.orders){let q=Math.min(o.pending,unitCap('receiving')-total('receiving'));s.inv.receiving[o.product]+=q;o.pending-=q;o.received+=q}syncStock()}
function orderProduct(p,boxes){if(!IDS.includes(p)||!Number.isInteger(boxes)||boxes<1||boxes>1000)return false;const cost=boxes*6*GOODS[p].cost;if(s.cash<cost)return false;s.cash-=cost;s.purchases+=cost;s.purchased[p]+=boxes*6;s.orders.push({product:p,total:boxes*6,received:0,pending:boxes*6});receive();return true}
function demandFactor(p,price,profile){let sensitivity=profile==='Econômico'?1.25:profile==='Família'?.9:.6;return Math.max(.05,Math.min(.98,1-(price/GOODS[p].reference-.6)*sensitivity))}
function profileFor(id){return ['Econômico','Família','Seletivo'][(id-1)%3]}
spawnCustomer=function(){if(s.customers.length>=6)return;let id=s.nextCustomer++,profile=profileFor(id),r=random(),p=profile==='Seletivo'?(r<.7?'cafe':'leite'):profile==='Família'?(r<.55?'leite':'arroz'):(r<.75?'arroz':'leite');let quantity=profile==='Família'?2+Math.floor(random()*3):profile==='Seletivo'?1+Math.floor(random()*2):1;s.customers.push({id,profile,product:p,quantity,room:'street',pos:[id%2?35:760,350],state:'enter',basket:false,price:0,progress:0,serving:false,path:[],goal:''})};
function reserve(c){let p=c.product;if(random()>demandFactor(p,s.prices[p],c.profile)){s.expensive++;s.byProduct[p].priceLost++;c.state='exit';say(`${c.profile}: desistiu de ${GOODS[p].name} pelo preço.`);return false}if(s.inv.sales[p]<c.quantity){s.missed++;s.byProduct[p].stockLost++;c.state='exit';say(`${c.profile}: faltaram ${c.quantity} unidades de ${GOODS[p].name}.`);return false}s.inv.sales[p]-=c.quantity;c.basket=true;c.price=s.prices[p];c.state='queue';syncStock();return true}
function duration(){return s.upgrades.includes('scanner')?1.5:3}
function completeSale(c){let p=c.product,revenue=c.quantity*c.price,cost=c.quantity*GOODS[p].cost;c.basket=false;s.sold[p]+=c.quantity;s.revenue+=revenue;s.cost+=cost;s.cash+=revenue;s.byProduct[p].sold+=c.quantity;s.byProduct[p].revenue+=revenue;s.byProduct[p].cost+=cost;s.metrics[s.mode].sales++;c.state='exit';c.serving=false;c.goal='';syncStock();say(`Vendeu ${c.quantity} ${GOODS[p].name}: +$${revenue.toFixed(2)} • margem $${(revenue-cost).toFixed(2)}.`)}
function serviceClick(){if(!atCheckout())return say('Aproxime-se do caixa.',true);s.metrics[s.mode].clicks++;if(s.mode==='continuous'){s.continuous=!s.continuous;say(s.continuous?'Atendimento contínuo ligado enquanto você estiver no caixa.':'Atendimento contínuo pausado.');return}let c=queue()[0];if(!c)return say('Nenhum cliente na fila.');if(Math.hypot(c.pos[0]-700,c.pos[1]-230)>8)return say('Aguarde o primeiro cliente chegar ao caixa.');c.serving=true}
$('serve').onclick=serviceClick;
function setMode(mode){if(!['manual','continuous'].includes(mode))return;s.mode=mode;s.continuous=false;for(let c of s.customers)c.serving=false;say('Modo de teste: '+(mode==='manual'?'iniciar cada venda.':'iniciar atendimento contínuo junto ao caixa.'))}
function buyUpgrade(key){let u=UPGRADES[key];if(!u||s.upgrades.includes(key)||s.cash<u.cost)return false;s.cash-=u.cost;s.investments+=u.cost;s.upgrades.push(key);if(key==='workflow')$('task').innerHTML='<option>Parado</option><option>Transportar</option><option>Repor</option><option>Abastecer</option>';say(`Melhoria adquirida: ${u.name}.\nCusto: $${u.cost.toFixed(2)} • saldo: $${s.cash.toFixed(2)}.\n${u.description}`);return true}
function shelfTarget(p){return s.upgrades.includes('shelf')?({arroz:30,leite:18,cafe:12})[p]:GOODS[p].target}
function workerJob(assignedTask=s.task){let task=assignedTask;if(task==='Parado'){workerMessage='Parado por sua ordem.';return null}let candidates=IDS.filter(p=>s.inv.sales[p]<shelfTarget(p)&&(s.inv.pallet[p]+s.inv.rack[p])>0).sort((a,b)=>s.inv.sales[a]/shelfTarget(a)-s.inv.sales[b]/shelfTarget(b));if(task==='Repor'||task==='Abastecer'){if(total('sales')<unitCap('sales')&&candidates.length){let p=candidates[0];return {p,from:s.inv.pallet[p]?'pallet':'rack',to:'sales',quantity:Math.min(6,shelfTarget(p)-s.inv.sales[p])}}if(task==='Repor'){workerMessage=total('sales')>=unitCap('sales')?'Expositor cheio. Aguarda vendas.':'Sem produto no depósito para as metas de reposição.';return null}}
if(task==='Transportar'||task==='Abastecer'){let p=IDS.find(p=>s.inv.receiving[p]>0),to=total('pallet')<unitCap('pallet')?'pallet':'rack';if(!p){workerMessage=pendingUnits()?'Aguardando descarga automática.':'Aguardando mercadoria no recebimento.';return null}if(total(to)>=unitCap(to)){workerMessage='Depósito cheio. Libere espaço.';return null}return {p,from:'receiving',to,quantity:6}}return null}
const staffPaths=[{goal:'',path:[]},{goal:'',path:[]}];
const staffMessages=['Aguardando atividade.','Aguardando atividade.'];
function staffActor(index){return index===0?{pos:s.worker,room:s.workerRoom,task:s.task,dest:s.dest}:s.worker2}
function staffSet(index,field,value){if(index===0){if(field==='room')s.workerRoom=value;else if(field==='pos')s.worker=value;else if(field==='dest')s.dest=value}else s.worker2[field]=value}
function staffWalk(index,room,to,dt){let actor=staffActor(index),nav=staffPaths[index],point=to,door=null;if(actor.room!==room){door=doors[actor.room].find(d=>d.to===room);if(!door)return false;point=door.p}let key=actor.room+':'+room+':'+point.join(',');if(nav.goal!==key){nav.path=route(actor.room,actor.pos,point);nav.goal=key}if(!nav.path){staffMessages[index]='Caminho bloqueado. Carga preservada.';return false}if(!follow(actor.pos,nav.path,125,dt))return false;if(door){staffSet(index,'room',door.to);staffSet(index,'pos',[...door.spawn]);nav.goal='';return false}return Math.hypot(actor.pos[0]-to[0],actor.pos[1]-to[1])<4}
function stepWorkerActor(index,dt){const actor=staffActor(index),slot=index===0?'worker':'worker2';if(total(slot)){let p=IDS.find(p=>s.inv[slot][p]>0),dest=actor.dest,point=places[dest];staffMessages[index]=`Levando ${s.inv[slot][p]} ${GOODS[p].name} para ${point[2]}.`;if(total(dest)>=unitCap(dest)){staffMessages[index]='Destino cheio. Mantém carga e aguarda espaço.';return}if(staffWalk(index,stationRoom(dest),[point[0]+(index===0?-16:16),point[1]+90],dt))transferUnits(slot,dest,p,s.inv[slot][p]);return}let job=workerJob(actor.task);if(!job){staffMessages[index]=workerMessage;return}let point=places[job.from];staffMessages[index]=`Buscando ${GOODS[job.p].name} em ${point[2]}.`;if(staffWalk(index,stationRoom(job.from),[point[0]+(index===0?-16:16),point[1]+90],dt)){transferUnits(job.from,slot,job.p,Math.min(job.quantity,unitCap(job.to)-total(job.to)));staffSet(index,'dest',job.to);staffPaths[index].goal=''}}
function stepWorker(dt){stepWorkerActor(0,dt);stepWorkerActor(1,dt);workerMessage=staffMessages[0]}

function finishDay(){s.open=false;s.closing=false;s.cash-=12;let result={day:s.day,revenue:s.revenue,cost:s.cost,purchases:s.purchases,investments:s.investments,profit:s.revenue-s.cost-12,cash:s.cash,missed:s.missed,expensive:s.expensive,products:JSON.parse(JSON.stringify(s.byProduct)),metrics:JSON.parse(JSON.stringify(s.metrics))};s.history.push(result);if(s.history.length>30)s.history.shift();modal('Fechamento • dia '+s.day,reportText(result));s.day++;s.revenue=s.cost=s.purchases=s.investments=s.missed=s.expensive=0;for(let p of IDS)s.byProduct[p]={sold:0,revenue:0,cost:0,stockLost:0,priceLost:0};s.continuous=false}
function reportText(r){return `Receita $${r.revenue.toFixed(2)} • CMV $${r.cost.toFixed(2)}\nDespesas $12 • lucro operacional $${r.profit.toFixed(2)}\nCompras $${r.purchases.toFixed(2)} • melhorias $${r.investments.toFixed(2)}\nCaixa $${r.cash.toFixed(2)}\nPerdas por falta: ${r.missed} • recusas por preço: ${r.expensive}\n\n`+IDS.map(p=>`${GOODS[p].name}: ${r.products[p].sold} un., margem $${(r.products[p].revenue-r.products[p].cost).toFixed(2)}, faltas ${r.products[p].stockLost}, preço ${r.products[p].priceLost}`).join('\n')+'\n\nTeste de caixa (acumulado):\n'+Object.entries(r.metrics).map(([k,m])=>`${k}: ${m.sales} compras, ${m.clicks} toques, ${Math.round(m.seconds)}s no caixa`).join('\n')+'\n\nCompare os modos e registre sua experiência; as métricas não medem diversão. Compras e melhorias afetam caixa, não o lucro operacional.'}
$('shop').onclick=()=>{if(s.open){s.closing=true;say('Entrada encerrada. Termine os clientes presentes.');if(!s.customers.length)finishDay()}else{s.open=true;s.arrival=2;say('Loja aberta. Clientes procuram produtos e preços diferentes.')}};
step=function(dt){receive();if(playerPath.length&&follow(s.player,playerPath,210,dt)){target=null;if(doorTarget){s.room=doorTarget.to;s.player=[...doorTarget.spawn];doorTarget=null}}stepWorker(dt);if(!atCheckout())s.continuous=false;else if(s.open)s.metrics[s.mode].seconds+=dt;if(s.open&&!s.closing){s.arrival+=dt;if(s.arrival>=5){s.arrival=0;spawnCustomer()}}let line=queue();for(let c of s.customers){if(c.state==='enter'&&customerWalk(c,[400,310],dt)){c.room='shop';c.pos=[400,370];c.state='browse';c.goal=''}else if(c.state==='browse'&&customerWalk(c,[280,280],dt)){reserve(c);c.goal=''}else if(c.state==='queue'){let index=line.indexOf(c);if(index<0)continue;let ready=customerWalk(c,QUEUE[index],dt);if(index===0&&ready&&atCheckout()){if(s.mode==='continuous'&&s.continuous)c.serving=true;if(c.serving&&(s.mode==='manual'||s.continuous)){c.progress=Math.min(3,c.progress+dt*3/duration());if(c.progress>=3)completeSale(c)}}}else if(c.state==='exit'&&customerWalk(c,[400,410],dt)){c.room='street';c.pos=[400,340];c.state='leave';c.goal=''}else if(c.state==='leave'&&customerWalk(c,[c.id%2?35:760,350],dt))c.done=true}s.customers=s.customers.filter(c=>!c.done);receive();if(s.closing&&!s.customers.length)finishDay();stepStreet(dt);error=Math.max(0,error-dt);syncStock();update();};
$('take').onclick=()=>{let k=near(),q=k?transferUnits(k,'player',transportSelected,unitCap('player')-total('player')):0;say(q?`Retirou ${q} unidades de ${GOODS[transportSelected].name}.`:'Sem produto selecionado disponível, longe do estoque ou carga cheia.',!q)};
$('drop').onclick=()=>{let k=near(),q=k?transferUnits('player',k,transportSelected,s.inv.player[transportSelected]):0;say(q?`Depositou ${q} unidades de ${GOODS[transportSelected].name}.`:'Destino cheio, distante ou sem este produto na carga.',!q)};
$('buy').onclick=()=>{let n=Number($('quantity').value),p=selected,cost=n*6*GOODS[p].cost,ok=orderProduct(p,n);if(!ok)return say('Pedido não realizado: informe de 1 a 1000 caixas e confira o saldo disponível.',true);let o=s.orders[s.orders.length-1];say(`${n} caixas = ${n*6} unidades de ${GOODS[p].name} encomendadas.\nCusto: $${cost.toFixed(2)} • saldo: $${s.cash.toFixed(2)}.\nRecebidas: ${o.received} unidades • aguardando espaço: ${o.pending} unidades.`)};
$('queue').onclick=()=>modal('Entregas por produto',s.orders.map((o,i)=>`#${i+1} ${GOODS[o.product].name}: ${o.received}/${o.total} unidades recebidas • ${o.pending} pendentes`).join('\n')||'Sem pedidos.');
$('task').onchange=()=>{let t=$('task').value;if(t==='Abastecer'&&!s.upgrades.includes('workflow'))return;s.task=t;say('Atividade atribuída: '+t+'. A carga em trânsito é entregue antes da mudança.')};
$('price').oninput=()=>{let v=Number($('price').value),g=GOODS[selected];if(Number.isFinite(v)&&v>=g.reference*.5&&v<=g.reference*2)s.prices[selected]=v;update()};
function selectProduct(p){if(!IDS.includes(p))return;selected=p;$('product').value=p;$('price').min=GOODS[p].reference*.5;$('price').max=GOODS[p].reference*2;$('price').step=.25;$('price').value=s.prices[p];update()}
function selectTransportProduct(p){if(!IDS.includes(p))return;transportSelected=p;$('quickProduct').value=p;update()}
$('product').onchange=() =>selectProduct($('product').value);
function contextEconomy(){let k=near(),d=nearbyDoor();$('contextDoor').hidden=!d;if(d)$('contextDoor').textContent=d.name;$('take').hidden=!k;$('drop').hidden=!k;$('serve').hidden=!atCheckout();$('unload').hidden=true;if(k){$('take').textContent='Retirar '+GOODS[transportSelected].name;$('drop').textContent=k==='sales'?'Repor '+GOODS[transportSelected].name:'Depositar '+GOODS[transportSelected].name;$('take').disabled=!s.inv[k][transportSelected]||total('player')>=unitCap('player');$('drop').disabled=!s.inv.player[transportSelected]||total(k)>=unitCap(k);$('contextHint').textContent=places[k][2]+': '+IDS.map(p=>`${GOODS[p].name} ${s.inv[k][p]}`).join(' • ')+` | livre ${unitCap(k)-total(k)} un.`}else $('contextHint').textContent=atCheckout()?'Caixa • permaneça aqui para registrar as compras.':d?d.name:'Toque no destino para caminhar; escolha o produto da carga abaixo.';
let c=queue()[0];$('serve').disabled=s.mode==='manual'&&(!c||c.serving||Math.hypot(c.pos[0]-700,c.pos[1]-230)>8);$('serve').textContent=s.mode==='continuous'?(s.continuous?'Pausar atendimento contínuo':'Iniciar atendimento contínuo'):c?.serving?'Registrando…':'Atender próximo cliente';$('checkoutStatus').textContent=`Fila: ${queue().length}`+(c?` • ${c.profile}: ${c.quantity} ${GOODS[c.product].name} • ${Math.floor(c.progress/3*100)}%`:'')+' • '+checkoutFeedback(c)}
function checkoutFeedback(c){if(!c)return s.mode==='continuous'&&s.continuous?'Atendimento contínuo ativo — aguardando cliente.':'Caixa aguardando cliente.';if(c.progress>0||c.serving){if(!atCheckout())return 'Atendimento pausado — volte ao caixa.';if(s.mode==='continuous'&&!s.continuous)return 'Atendimento pausado — toque em Iniciar atendimento contínuo.';if(!c.serving)return 'Atendimento pausado — toque em Atender próximo cliente.';return 'Atendimento em andamento — permaneça no caixa.'}return s.mode==='continuous'&&s.continuous?'Atendimento contínuo ativo — aguardando cliente chegar.':'Aguardando atendimento no caixa.'}

function purchaseEconomy(){let n=Number($('quantity').value),ok=Number.isInteger(n)&&n>=1&&n<=1000,cost=n*6*GOODS[selected].cost,free=unitCap('receiving')-total('receiving'),fits=ok?Math.min(n*6,Math.max(0,free-pendingUnits())):0;$('buy').disabled=!ok||cost>s.cash;$('buy').textContent=ok?`Comprar ${n} caixas • $${cost.toFixed(2)}`:'Quantidade inválida';$('purchaseInfo').textContent=`Caixa com 6 unidades • custo unitário $${GOODS[selected].cost.toFixed(2)}\n`+(ok?`Total $${cost.toFixed(2)} • saldo após compra $${(s.cash-cost).toFixed(2)}\nAté ${fits} unidades cabem na descarga; ${n*6-fits} ficam pendentes.\n`:'Informe de 1 a 1000 caixas.\n')+`Recebimento livre: ${free} un. • depósito livre: ${unitCap('pallet')+unitCap('rack')-total('pallet')-total('rack')} un.`;$('purchaseInfo').style.whiteSpace='pre-line'}
$('quantity').oninput=purchaseEconomy;
update=function(){syncStock();$('hud').textContent=`Dia ${s.day} • ${s.closing?'Fechando':s.open?'Aberta':'Fechada'} • $${s.cash.toFixed(2)}`;$('shop').textContent=s.closing?'Conclua a fila':s.open?'Fechar loja':'Abrir loja';$('load').textContent='Sua carga: '+IDS.map(p=>`${GOODS[p].name} ${s.inv.player[p]}`).join(' • ')+` | ${total('player')}/${unitCap('player')} un.`;$('priceText').textContent=`$${s.prices[selected].toFixed(2)}/un. • margem $${(s.prices[selected]-GOODS[selected].cost).toFixed(2)}`;$('workerStatus').textContent=`Funcionário 1 • ${s.task}: ${staffMessages[0]}`;$('workerStatus2').textContent=`Funcionário 2 • ${s.worker2.task}: ${staffMessages[1]}`;refreshSecondTask();$('productInfo').textContent=IDS.map(p=>`${GOODS[p].name}: preço $${s.prices[p].toFixed(2)} • referência $${GOODS[p].reference.toFixed(2)} • expositor ${s.inv.sales[p]}/${shelfTarget(p)} un. • vendido ${s.byProduct[p].sold} • faltas ${s.byProduct[p].stockLost} • recusas por preço ${s.byProduct[p].priceLost}`).join('\n');$('demandInfo').textContent='Aceitação estimada de '+GOODS[selected].name+': '+['Econômico','Família','Seletivo'].map(profile=>`${profile} ${Math.round(100*demandFactor(selected,s.prices[selected],profile))}%`).join(' • ')+'. É uma hipótese do protótipo, não uma previsão garantida de vendas.';for(let key of Object.keys(UPGRADES)){let owned=s.upgrades.includes(key);$('upgrade-'+key).disabled=owned||s.cash<UPGRADES[key].cost;$('upgrade-'+key).textContent=owned?'Adquirido':`Comprar • $${UPGRADES[key].cost}`;}$('displayStock').textContent='Expositor • '+IDS.map(p=>`${GOODS[p].name}: ${s.inv.sales[p]>0?s.inv.sales[p]+' un.':'Esgotado'}`).join(' | ')+' • Cada caixinha representa até 6 unidades.';contextEconomy();purchaseEconomy();if(!conserved())throw Error('Conservação por produto violada')};
function verifyEconomy(v){try{if(v&&v.inv&&!v.inv.worker2&&!v.worker2){v.inv.worker2={arroz:0,leite:0,cafe:0};v.worker2={pos:[580,310],room:'stock',task:'Parado',dest:'pallet'}}if(!v.worker2||!Array.isArray(v.worker2.pos)||v.worker2.pos.length!==2||!v.worker2.pos.every(Number.isFinite)||!['shop','stock'].includes(v.worker2.room)||!['Parado','Transportar','Repor','Abastecer'].includes(v.worker2.task)||v.worker2.task==='Abastecer'&&!v.upgrades.includes('workflow')||!places[v.worker2.dest])return false;if(v.version!==8||!LOCS.every(k=>v.inv[k])||!IDS.every(p=>Number.isInteger(v.purchased[p])&&v.purchased[p]>=0&&Number.isInteger(v.sold[p])&&v.sold[p]>=0&&Number.isFinite(v.prices[p])&&v.prices[p]>=GOODS[p].reference*.5&&v.prices[p]<=GOODS[p].reference*2))return false;if(!['street','shop','stock'].includes(v.room)||!['shop','stock'].includes(v.workerRoom)||!['Parado','Transportar','Repor','Abastecer'].includes(v.task)||!['manual','continuous'].includes(v.mode)||typeof v.open!=='boolean'||typeof v.closing!=='boolean'||typeof v.continuous!=='boolean'||!Array.isArray(v.upgrades)||v.upgrades.some(k=>!UPGRADES[k])||new Set(v.upgrades).size!==v.upgrades.length||v.task==='Abastecer'&&!v.upgrades.includes('workflow')||!places[v.dest])return false;for(let k of ['cash','day','revenue','cost','purchases','investments','missed','expensive','arrival','nextCustomer','rng'])if(!Number.isFinite(v[k]))return false;if(v.day<1||v.nextCustomer<1||!Array.isArray(v.history)||!Array.isArray(v.customers)||v.customers.length>6)return false;for(let k of ['player','worker'])if(!Array.isArray(v[k])||v[k].length!==2||!v[k].every(Number.isFinite))return false;for(let k of LOCS)for(let p of IDS)if(!Number.isInteger(v.inv[k][p])||v.inv[k][p]<0)return false;for(let o of v.orders)if(!IDS.includes(o.product)||!['total','received','pending'].every(k=>Number.isInteger(o[k])&&o[k]>=0)||o.total!==o.received+o.pending)return false;let seen=new Set();for(let c of v.customers){if(!IDS.includes(c.product)||!['Econômico','Família','Seletivo'].includes(c.profile)||!Number.isInteger(c.id)||seen.has(c.id)||!Number.isInteger(c.quantity)||c.quantity<1||c.quantity>6||!['enter','browse','queue','exit','leave'].includes(c.state)||!['street','shop'].includes(c.room)||typeof c.basket!=='boolean'||c.basket&&c.state!=='queue'||!Number.isFinite(c.price)||!Number.isFinite(c.progress)||c.progress<0||c.progress>3||!Array.isArray(c.pos)||c.pos.length!==2||!c.pos.every(Number.isFinite))return false;seen.add(c.id)}for(let p of IDS)for(let k of ['sold','revenue','cost','stockLost','priceLost'])if(!Number.isFinite(v.byProduct[p][k])||v.byProduct[p][k]<0)return false;for(let mode of ['manual','continuous'])for(let k of ['clicks','sales','seconds'])if(!Number.isFinite(v.metrics[mode][k])||v.metrics[mode][k]<0)return false;let prev=s,result=false;try{s=v;result=LOCS.every(k=>total(k)<=unitCap(k))&&conserved()}finally{s=prev}return result}catch{return false}}
function resetNavigation(){for(let n of staffPaths){n.goal='';n.path=[]}playerPath=[];workerPath=[];workerGoal='';doorTarget=null;target=null;for(let c of s.customers){c.goal='';c.path=[]}s.continuous=false;syncStock()}
function migrateLegacy(v){if(!v||!v.stock||!Array.isArray(v.orders))return null;let n=freshEconomy();for(let k of LOCS){let q=(k==='worker2'?0:v.stock[k])*6;if(!Number.isInteger(q)||q<0)return null;n.inv[k].arroz=q}n.purchased.arroz=v.purchased*6;n.sold.arroz=v.sold*6;n.orders=v.orders.map(o=>({product:'arroz',total:o.total*6,received:o.received*6,pending:o.pending*6}));for(let k of ['cash','day','revenue','purchases','missed','open','closing','task','room','workerRoom','player','worker','dest','nextCustomer','arrival'])if(v[k]!==undefined)n[k]=v[k];n.cost=v.cost||0;n.prices.arroz=v.price>=1&&v.price<=4?v.price:2;if(v.investment==='Carrinho')n.upgrades.push('cart');if(v.investment==='Expositor')n.upgrades.push('shelf');n.customers=(v.customers||[]).map(c=>({...c,product:'arroz',profile:'Família',quantity:6}));return verifyEconomy(n)?n:null}
$('save').onclick=()=>{try{if(!verifyEconomy(s))throw Error();localStorage.setItem('entre-mobile-08',JSON.stringify(s));say('Progresso 0.8.2 salvo. O salvamento anterior foi preservado.')}catch{say('Não foi possível salvar. Estado inválido ou armazenamento indisponível.',true)}};
$('restore').onclick=()=>{try{let raw=localStorage.getItem('entre-mobile-08'),v=raw?JSON.parse(raw):migrateLegacy(JSON.parse(localStorage.getItem('entre-mobile-02')));if(!verifyEconomy(v))throw Error();s=v;s.mode='continuous';resetNavigation();$('task').innerHTML='<option>Parado</option><option>Transportar</option><option>Repor</option>'+(s.upgrades.includes('workflow')?'<option>Abastecer</option>':'');$('task').value=s.task;$('cashMode').value=s.mode;selectProduct(selected);say(raw?'Progresso carregado.':'Salvamento anterior importado: mercadorias genéricas convertidas em arroz. O original foi preservado.')}catch{say('Nenhum salvamento válido. Estado atual preservado.',true)}};
$('cashMode').onchange=()=>setMode($('cashMode').value);
$('lastReport').onclick=()=>modal('Último fechamento',s.history.length?reportText(s.history[s.history.length-1]):'Feche um dia para gerar o relatório por produto.');
for(let key of Object.keys(UPGRADES))$('upgrade-'+key).onclick=()=>{if(!buyUpgrade(key))say('Melhoria já adquirida ou caixa insuficiente.',true)};
const economyDraw=draw;draw=function(){economyDraw();if(s.worker2.room===s.room)person(s.worker2.pos,'#a58bd4','Funcionário 2',total('worker2'));if(s.workerRoom===s.room)text('1',s.worker[0],s.worker[1]-36,15,'#f2ba69');for(let c of s.customers)if(c.room===s.room&&c.basket)text(`${c.quantity} ${GOODS[c.product].name}`,c.pos[0],c.pos[1]-36,14,GOODS[c.product].color);if(s.room==='shop'){drawStockedShelf();let c=queue()[0];if(c&&(c.progress>0||c.serving)){let paused=!atCheckout()||s.mode==='continuous'&&!s.continuous||!c.serving;text(paused?'PAUSADO':'REGISTRANDO',560,194,15,paused?'#8e3725':'#244d3c')}}};

let secondTaskOptions='';
function refreshSecondTask(){let options='<option>Parado</option><option>Transportar</option><option>Repor</option>'+(s.upgrades.includes('workflow')?'<option>Abastecer</option>':'');if(options!==secondTaskOptions){$('task2').innerHTML=options;secondTaskOptions=options}$('task2').value=s.worker2.task}
$('task2').onchange=()=>{let value=$('task2').value;if(!['Parado','Transportar','Repor','Abastecer'].includes(value)||value==='Abastecer'&&!s.upgrades.includes('workflow'))return;s.worker2.task=value;say('Funcionário 2: '+value+'. A entrega em trânsito será concluída antes da troca.')} ;
selectProduct('arroz');say('Versão 0.8.8: use o computador no estoque para comprar mercadoria e ajustar preços. Clientes compram unidades, não caixas inteiras.');

function shelfPackages(quantity){const boxes=[];for(let left=quantity;left>0;left-=6)boxes.push(Math.min(left,6));return boxes}
function drawStockedShelf(){
 // Mantém o móvel na área de colisão já aprovada: x170–390, y150–235.
 text(`Expositor • ${total('sales')}/${unitCap('sales')} un.`,280,137,15,'#263e38');
 rect(174,155,220,86,'#0002');
 rect(170,150,220,85,'#b58a58');
 rect(176,155,208,72,'#dbbc87');
 for(let level=0;level<3;level++){
  let y=155+level*24;
  rect(176,y,208,17,level%2?'#d0af79':'#dabc88');
  rect(172,y+18,216,5,'#8b5e36');
  rect(172,y+18,216,2,'#efc994');
 }
 for(let i=0;i<=3;i++)rect(170+i*72,150,5,85,'#956c43');
 IDS.forEach((p,index)=>{
  const left=180+index*72,n=s.inv.sales[p];
  shelfPackages(n).forEach((units,j)=>{
   const x=left+(j%4)*15,y=157+Math.floor(j/4)*24;
   rect(x+1,y+2,12,15,'#0002');
   rect(x,y,12,15,GOODS[p].color);
   rect(x,y,12,3,'#edcf9d');
   rect(x+5,y,2,10,'#f5e2b4');
   // A faixa inferior representa o preenchimento da caixa parcial.
   rect(x+1,y+12,10,2,'#7b674d');
   rect(x+1,y+12,10*units/6,2,'#325f45');
  });
  rect(left-2,232,66,38,'#f1dfb6');
  text(GOODS[p].name,left+31,243,11,'#3d3829');
  text(`${n} un.`,left+31,255,11,'#264d38');
  if(n===0)text('Esgotado',left+31,267,10,'#8b3d27');
 });
 // Pernas e travessas reforçam a silhueta de prateleira física.
 rect(170,231,5,12,'#74502f');rect(385,231,5,12,'#74502f');
}
